 checkLayers(s.front);checkLayers(s.back);for(const v of s.versions){exact(v,['id','front','back'],'scene version');checkLayers(v.front);checkLayers(v.back);}for(const undo of [...s.undo,...s.redo]){exact(undo,['front','back'],'undo');checkLayers(undo.front);checkLayers(undo.back);}for(const c of m.cart){exact(c,['versionId','size','region','quote','front','back'],'cart');if(!['valid','expired'].includes(c.quote))throw Error('Invalid commerce quote');checkLayers(c.front);checkLayers(c.back);}
