 if(name==='bundle-stale')m.quoteState='stale';if(name==='bundle-expired')m.quoteState='expired';if(name==='bundle-insufficient')m.wallet={...m.wallet,availableUnits:2};if(name==='garment-only'){m.digital=false;m.garment=true;}if(name==='both-uses')m.garment=true;if(name==='no-downstream'){m.digital=false;m.garment=false;}if(name==='no-standard')m.standard=false;if(name==='region-blocked')m.region='EU';
 const post=['concepts-0','concepts-1','concepts-2','concepts-3','concept-unknown','provider-pending','persistence-pending','concept-failed','settlement-pending','refinement-1','refinement-2','refinement-skipped','refinement-pending','refinement-unknown','final-available','final-unavailable','final-reserved','final-running','final-unknown','final-delivered','final-charge-review','final-quality','final-revoked','history','account','export-restricted','export-expired','gallery-private','gallery-pending','gallery-published','gallery-rejected','gallery-revoked'];
 if(post.includes(name)){m.authorized=true;m.wallet={...m.wallet,availableUnits:30};m.slots=['delivered','delivered','delivered'];m.settlement='settled';m.stage=11;m.refinements=[1,2].map(n=>({state:'available',ordinal:n       ,packageId:'package-3x2-01',sourceVersionId:null}));}
 if(name==='concepts-0'||name==='provider-pending'){m.slots=['running','running','running'];m.stage=9;}
