function correctionCommand(m      ,action       ,p                       ,key       )                                 {if(action==='approve'&&m.correction.approvalReplay){return m.correction.approvalReplay.key===key&&m.correction.approvalReplay.payload===JSON.stringify(p)?{ok:true,message:'Existing approval; no credit authorization.'}:{ok:false,message:'Plan already frozen or replay conflict.'};}if(action==='approve'&&p.expectedRevision!==undefined&&p.expectedRevision!==m.revision)return {ok:false,message:'Stale brief revision rejected.'};if(action==='observe'&&!m.correction.conceptAvailable)return {ok:false,message:'Route unavailable; original operations held for review.'};if(!['verified-final-failure','retry-final-quote'].includes(action))return null;try{requireThat(Object.keys(p).every(k=>k==='expectedRevision'),'Unknown command field');requireThat(p.expectedRevision===undefined||p.expectedRevision===m.revision,'Revision conflict');if(action==='verified-final-failure'){requireThat(m.final==='running','Only verified fixture failure may release');m.correction.recovery=recovery(m,'failure',m.correction.originalClosed);m.correction.releasedFinal=true;m.wallet={...m.wallet,availableUnits:m.wallet.availableUnits+12};m.final='none';m.stage=14;reconcileWallet(m);}else{requireThat(m.correction.releasedFinal,'Verified released outcome required');m.correction.recovery=null;m.finalSequence++;m.finalQuoteId=null;m.quoteRevision++;m.quoteSource=m.selected;m.quoteState='valid';m.stage=14;}m.revision++;return {ok:true,message:'Simulated verified release. Fresh consent required; original closure preserved.'};}catch(e){return {ok:false,message:(e         ).message};}}
const extraScenarios=['director-quota','concept-route-before','concept-route-after','promo-persistence','final-uncharged-initial','final-uncharged-revision','final-unknown-revision','credits-reconciliation','remedy-under-review','remedy-approved','remedy-completed','export-v1-v2','export-pending']         ;
